import { useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'store';
import { geAllPermission } from 'store/slices/userList';
import { useParams, useNavigate } from 'react-router-dom';
import {
    Box,
    Grid,
    Tabs,
    Tab,
    FormControlLabel,
    Switch,
    Typography,
    TextField,
    Divider,
    Button,
    Accordion,
    AccordionSummary,
    AccordionDetails
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ApiRequest from 'utils/apiService';
import useSnackbar from 'hooks/useSnackbar';
import MainCard from 'ui-component/cards/MainCard';
import { useFormik } from 'formik';
import * as yup from 'yup';
import { useTheme } from '@mui/styles';

const RolePermissionForm = () => {
    const theme = useTheme();
    const { id: roleId } = useParams(); // If roleId exists → Edit Mode, else Add Mode
    const dispatch = useDispatch();
    const { entities } = useSelector((state) => state.usersList);
    const allPermissions = entities?.permissions || [];
    const { showSnackbar } = useSnackbar();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [tabValue, setTabValue] = useState(0);
    const [roleData, setRoleData] = useState(null);

    useEffect(() => {
        dispatch(geAllPermission({ pagination: false }));
    }, [dispatch]);

    useEffect(() => {
        if (!roleId) return; // Only fetch data if editing

        const fetchRoleData = async () => {
            try {
                const response = await ApiRequest('GET', `/users/roles/?id=${roleId}`);
                setRoleData(response?.data || {});
            } catch (error) {
                showSnackbar(error.message, 'error');
            }
        };

        fetchRoleData();
    }, [roleId]);

    /** Transform permissions into structured format */
    const structuredPermissions = allPermissions
        .filter((perm) => perm.permission_type === 'menu')
        .map((menu) => ({
            ...menu,
            enabled: roleData?.permissionIds?.includes(menu.id) || false,
            children: allPermissions
                .filter((submenu) => submenu.parent_id === menu.id && submenu.permission_type === 'submenu')
                .map((submenu) => ({
                    ...submenu,
                    enabled: roleData?.permissionIds?.includes(submenu.id) || false,
                    children: allPermissions
                        .filter((action) => action.parent_id === submenu.id)
                        .map((action) => ({
                            ...action,
                            enabled: roleData?.permissionIds?.includes(action.id) || false
                        }))
                }))
        }));

    const formik = useFormik({
        initialValues: {
            roleName: roleData?.name || '',
            status: roleData?.status ?? true, // ✅ Default to true (enabled) when adding a role
            permissions: structuredPermissions
        },
        enableReinitialize: true,
        validationSchema: yup.object({
            roleName: yup.string().required('Role Name is required')
        }),
        onSubmit: async (values) => {
            setLoading(true);
            try {
                const permissionIds = values.permissions
                    .flatMap((menu) => [
                        menu.enabled ? menu.id : null,
                        ...menu.children.flatMap((submenu) => [
                            submenu.enabled ? submenu.id : null,
                            ...submenu.children.map((action) => (action.enabled ? action.id : null))
                        ])
                    ])
                    .filter(Boolean);

                const uniquePermissionIds = [...new Set(permissionIds)];
                const requestData = {
                    roleName: values.roleName,
                    status: values.status, // ✅ Include status in request payload
                    permissionIds: uniquePermissionIds
                };

                if (roleId) {
                    // ✅ Edit Case: Compare with previous permissions
                    const prevPermissionIds = roleData?.permissionIds || [];

                    requestData.prevPermissionIds = prevPermissionIds;
                    requestData.permissionsToInsert = uniquePermissionIds.filter((permId) => !prevPermissionIds.includes(permId));
                    requestData.permissionsToDelete = prevPermissionIds.filter((permId) => !uniquePermissionIds.includes(permId));

                    await ApiRequest('PUT', `/users/update-permission/${roleId}`, requestData);
                    showSnackbar('Role updated successfully!', 'success');
                } else {
                    // ✅ Add Case: Only send enabled permissions (No need for prevPermissionIds)
                    await ApiRequest('POST', `/users/addRole`, requestData);
                    showSnackbar('Role created successfully!', 'success');
                }

                setTimeout(() => navigate('/employes/list', { replace: true }), 1000);
            } catch (error) {
                showSnackbar(error.message, 'error');
            } finally {
                setLoading(false);
            }
        }
    });

    /** Handles toggling of a menu and cascades the changes */
    const handleToggle = (id, level) => {
        const updatedPermissions = formik.values.permissions.map((menu) => {
            if (menu.id === id) {
                // Toggle the parent menu
                const isEnabled = !menu.enabled;
                return {
                    ...menu,
                    enabled: isEnabled,
                    children: menu.children.map((submenu) => ({
                        ...submenu,
                        enabled: isEnabled, // Enable all submenus when parent is enabled
                        children: submenu.children.map((action) => ({
                            ...action,
                            enabled: isEnabled // Enable all actions when parent is enabled
                        }))
                    }))
                };
            }

            return {
                ...menu,
                children: menu.children.map((submenu) => {
                    if (submenu.id === id) {
                        // Toggle submenu
                        const isEnabled = !submenu.enabled;
                        return {
                            ...submenu,
                            enabled: isEnabled,
                            children: submenu.children.map((action) => ({
                                ...action,
                                enabled: isEnabled // Enable all actions when submenu is enabled
                            }))
                        };
                    }

                    return {
                        ...submenu,
                        children: submenu.children.map((action) => {
                            if (action.id === id) {
                                // Toggle action independently (user choice)
                                return {
                                    ...action,
                                    enabled: !action.enabled
                                };
                            }
                            return action;
                        })
                    };
                })
            };
        });

        formik.setFieldValue('permissions', updatedPermissions);
    };

    let buttonText = 'Create Role';

    if (loading) {
        buttonText = 'Processing...';
    } else if (roleId) {
        buttonText = 'Update Role';
    }
    return (
        <MainCard sx={{ background: theme.palette.text.primary }}>
            <form onSubmit={formik.handleSubmit}>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <TextField
                            fullWidth
                            id="roleName"
                            name="roleName"
                            label="Role Name"
                            value={formik.values.roleName}
                            onChange={formik.handleChange}
                            error={formik.touched.roleName && Boolean(formik.errors.roleName)}
                            helperText={formik.touched.roleName && formik.errors.roleName}
                        />
                    </Grid>
                    <Grid item xs={12}>
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={formik.values.status}
                                    onChange={(event) => formik.setFieldValue('status', event.target.checked)}
                                />
                            }
                            label="Enable Role"
                            sx={{ color: theme.palette.text.dark }}
                        />
                    </Grid>

                    {/* Tabs for Menu Level */}
                    <Grid item xs={12}>
                        <Tabs value={tabValue} onChange={(_, newValue) => setTabValue(newValue)} variant="scrollable">
                            {formik.values.permissions.map((menu) => (
                                <Tab key={menu.id} label={menu.label} />
                            ))}
                        </Tabs>

                        {formik.values.permissions.map((menu, index) => (
                            <div role="tabpanel" hidden={tabValue !== index} key={menu.id}>
                                {tabValue === index && (
                                    <Box sx={{ p: 2, background: theme.palette.text.primary }}>
                                        <Typography variant="h6">{menu.label}</Typography>
                                        <Divider sx={{ my: 1 }} />
                                        <FormControlLabel
                                            control={<Switch checked={menu.enabled} onChange={() => handleToggle(menu.id, 'menu')} />}
                                            label={`Enable ${menu.label}`}
                                        />

                                        {menu.children.map((submenu) => (
                                            <Accordion key={submenu.id} sx={{ mt: 1, background: theme.palette.text.primary }}>
                                                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                                                    <FormControlLabel
                                                        control={
                                                            <Switch
                                                                checked={submenu.enabled}
                                                                onChange={() => handleToggle(submenu.id, 'submenu')}
                                                            />
                                                        }
                                                        label={submenu.label}
                                                        sx={{ color: theme.palette.text.dark }}
                                                    />
                                                </AccordionSummary>
                                                <AccordionDetails>
                                                    {submenu?.children.map((action) => (
                                                        <FormControlLabel
                                                            key={action.id}
                                                            control={
                                                                <Switch
                                                                    checked={action.enabled}
                                                                    onChange={() => handleToggle(action.id, 'action')}
                                                                />
                                                            }
                                                            label={action.label}
                                                            sx={{ color: theme.palette.text.dark }}
                                                        />
                                                    ))}
                                                </AccordionDetails>
                                            </Accordion>
                                        ))}
                                    </Box>
                                )}
                            </div>
                        ))}
                    </Grid>
                </Grid>

                <Box sx={{ mt: 2, textAlign: 'right' }}>
                    <Button type="submit" variant="contained" color="primary" disabled={loading}>
                        {buttonText}
                    </Button>
                </Box>
            </form>
        </MainCard>
    );
};

export default RolePermissionForm;
